"""Build a scoped proposal from the captured Allbag variant data. No prices/stock/origin promises."""
import json,re,unicodedata
from pathlib import Path
r=Path(__file__).resolve().parents[1]
audit=json.loads((r/'research/allbag-2026-10-31/observed-variants.json').read_text())
def slug(s):return re.sub('[^a-z0-9]+','-',unicodedata.normalize('NFKD',s.lower().replace('ł','l')).encode('ascii','ignore').decode()).strip('-')
def field(id,label,options):return dict(id=id,label=label,options=[dict(id=a,label=b) for a,b in options])
color_names={'Brązowa (kraft)':'Brązowy kraft','biała':'Biały','Biała':'Biały','czarna':'Czarny','Czarna':'Czarny','ecru':'Naturalny','granatowa':'Granatowy','Granatowa':'Granatowy','czerwona':'Czerwony','Czerwona':'Czerwony','zielona':'Zielony','Ciemnozielona':'Ciemnozielony','Jasnozielona':'Jasnozielony','Żółta':'Żółty'}
models=[('papier-plaski','Papier · uchwyt płaski','kraft','papierowy płaski','kraft-flat'),('papier-skrecany','Papier · uchwyt skręcany','kraft','papierowy skręcany','kraft-brown'),('bawelna','Bawełna · długie uchwyty','cotton','długie (70 cm)','cotton-long-natural'),('bawelna-krotkie','Bawełna · krótkie uchwyty','cotton','krótkie (35 cm)','cotton-short-natural'),('bawelna-dno','Bawełna · poszerzane dno','cotton','długie','cotton-bottom'),('bawelna-boki','Bawełna · dno i boki','cotton','długie','cotton-sides')]
products=[]
for source,(id,name,family,handle,photo) in zip(audit['products'],models):
 sizes={};colors={};weights={};matrix=[]
 for v in source['variants']:
  size='x'.join(f'{float(n)/10:g}' for n in re.findall(r'\d+(?:\.\d+)?',v['size']))
  sizes[size]=size.replace('x',' × ')
  color=color_names.get(v['colour'],v['colour']);cid=slug(color);colors[cid]=color
  row={'size':size,'stockColor':cid}
  if 'mat' in v:
   weight=re.search(r'\d+',v['mat'])[0];weights[weight]=weight+' g/m²';row['weight']=weight
  if row not in matrix:matrix.append(row)
 fields=[field('size','Format (cm)',sizes.items())]
 if weights:fields.append(field('weight','Gramatura',weights.items()))
 fields += [field('stockColor','Kolor gotowej torby',colors.items()),field('printMode','Strony nadruku',[('jednostronny','nadruk jednostronny'),('dwustronny-taki-sam','nadruk dwustronny — taki sam'),('dwustronny-rozne','nadruk dwustronny — różne projekty'),('bez-nadruku','bez nadruku')]),field('printing','Technika nadruku',[('screen','Sitodruk'),('digital','Druk DTG' if family=='cotton' else 'Druk cyfrowy')]),field('inkCount','Liczba kolorów nadruku',[(str(n),str(n)) for n in range(1,5)])]
 if family=='cotton':fields.append(field('digitalFormat','Format nadruku DTG',[('a5','A5 · 15 × 20 cm'),('a4','A4 · 20 × 30 cm'),('a4-plus','A4+ · 27 × 33 cm')]))
 products.append(dict(id=id,family=family,name=name,size=next(iter(sizes)),specs={'Uchwyt':handle,'Materiał':'Papier nielaminowany' if family=='kraft' else 'Bawełna'},fields=fields,variantMatrix=matrix,source=source['url'],photo=photo,pricing='quote',productionStatus='reference-proposal',confirmationRequired=['formats','stock-colors-per-format','paper-or-fabric-weight','printing-technology','print-area','minimum-quantity','pricing','lead-time']))
out=dict(schemaVersion=2,auditedAt='2026-10-31-allbag-32',scopeSource='User requested Allbag as provisional product reference; client excludes laminated bags and sacks.',families=[dict(id='kraft',name='Torby papierowe'),dict(id='cotton',name='Torby bawełniane')],products=products)
(r/'configuration/catalog-data.js').write_text('// Generated by tools/build-allbag-catalog.py. Reference proposal: merchant must confirm production capabilities.\nexport default '+json.dumps(out,ensure_ascii=False,indent=2)+';\n')
print(len(products),'constructions,',sum(len(p['variantMatrix']) for p in products),'distinct format/material/colour combinations')
